import json,re,statistics
from pathlib import Path
base=Path('/workspace/results/run100')
def boxes(s):
 # Good enough for the simple numeric GSM8K answers; supports one nesting level.
 return re.findall(r'\\boxed\{(?:[^{}]|\{[^{}]*\})*\}',s)
def num(s):
 s=s.replace('\\boxed{','').replace(',','').replace('$','').strip()
 if s.endswith('}'):s=s[:-1]
 s=s.replace('\\!','').replace('\\,','').strip()
 m=re.fullmatch(r'\\[d]?frac\{(-?\d+(?:\.\d+)?)\}\{(-?\d+(?:\.\d+)?)\}',s)
 if m:
  try:return float(m.group(1))/float(m.group(2))
  except:return None
 try:return float(s.rstrip('%'))/(100 if s.endswith('%') else 1)
 except:return None
for kind,steps in [('rollouts',[1,50,100]),('val_generations',[0,50,100])]:
 print('\n'+kind)
 for step in steps:
  rs=[json.loads(x) for x in (base/kind/f'{step}.jsonl').read_text().splitlines()]
  bad=[]; comparable=0; noanswer=0
  for r in rs:
   bs=boxes(r['output'])
   if not bs:noanswer+=1;continue
   p=num(bs[-1]);g=num(r['gts'])
   if p is not None and g is not None:
    comparable+=1
    if abs(p-g)>1e-7 and r['score']>0:bad.append(r)
  print('step',step,'numeric_final_comparable',comparable,'no_box',noanswer,'rewarded_wrong_last_box',len(bad),'pct_all',round(100*len(bad)/len(rs),2))
  for r in bad[:3]:
   print(' gt',r['gts'],'last',boxes(r['output'])[-1],'score',r['score'],'all_boxes',boxes(r['output'])[-4:])
   print(' tail',repr(r['output'][-500:]))
PY

